  "material:day_pillar:甲辰:04:detail": {
    "id": "material:day_pillar:甲辰:04:detail",
    "text": "相手に合わせて話を聴き、誠実に受け止めるため相談を持ちかけられやすいです。受け取った内容は内側に留め置き、そのまま外へは出しません。",
    "refs": [
      "DP41-010"
    ],
    "kind": "astrological_interpretation",
    "scope": "common",
    "owner": {
      "family": "day_pillar",
      "key": "甲辰"
    },
    "reviewStatus": "legacy_unreviewed",
    "withheldReasons": []
  },
